def _sr_candidate(text):
    t=text.casefold()
    return any_phrase(t,['return','destroy','retain','retention','archiv','backup system','maintain a single copy','record copy'])
def _sr_windows(spans):
    texts=[]
    lows=[]
    flags=[]
    for s in spans:
        raw=s.get('text','')
        if not isinstance(raw,str):
            raw=str(raw)
        texts.append(raw)
        lows.append(raw.casefold())
        flags.append(_sr_candidate(raw))
    consumed=set()
    out=[]
    i=0
    while i<len(spans):
        if not flags[i] or i in consumed:
            i+=1
            continue
        ids=[spans[i].get('id')]
        t=lows[i]
        if i>0:
            p=texts[i-1].strip()
            if p.endswith(':') and spans[i-1].get('id') not in ids:
                ids=[spans[i-1].get('id')]+ids
        if ('no copies' in t or 'no copy' in t) and 'foregoing' in t and i>0 and flags[i-1]:
            pid=spans[i-1].get('id')
            if pid not in ids:
                ids=[pid]+ids
        if ('return' in t or 'destroy' in t) and 'in lieu of return' not in t:
            j=i+1
            limit=i+3
            if limit>len(spans):
                limit=len(spans)
            while j<limit:
                if 'in lieu of return' in lows[j]:
                    jid=spans[j].get('id')
                    if jid not in ids:
                        ids.append(jid)
                    consumed.add(j)
                    break
                j+=1
        out.append({'unit_ids':ids})
        i+=1
    return out
def _sr_window_text(spans,unit_ids):
    texts=[]
    found=[]
    for s in spans:
        sid=s.get('id')
        if sid in unit_ids:
            raw=s.get('text','')
            if not isinstance(raw,str):
                raw=str(raw)
            texts.append(raw)
            found.append(sid)
    return ' '.join(texts),found
def _sr_queries(spans):
    operations=['operative_disposal_effect','operative_retention_effect','disposal_actor_role']
    disposal_ops=['disposal_action_allocation','disposal_trigger_role','disposal_information_scope','disposal_exception_role']
    retention_ops=['retention_information_scope','retention_limitation_role']
    out=[]
    windows=_sr_windows(spans)
    i=0
    while i<len(windows):
        text,ids=_sr_window_text(spans,windows[i].get('unit_ids',[]))
        t=text.casefold()
        ops=[]
        ops.extend(operations)
        if 'return' in t or 'destroy' in t:
            ops.extend(disposal_ops)
        if any_phrase(t,['retain','retention','archiv','backup system','maintain a single copy','record copy','no copies','no copy']):
            ops.extend(retention_ops)
        j=0
        while j<len(ops):
            out.append({'id':'sr_'+str(i)+'_'+str(j),'operation':ops[j],'unit_ids':ids})
            j+=1
        i+=1
    return out
def _sr_choice(answers,qid,operation,unresolved):
    a=answers.get(qid)
    if a is None:
        unresolved.append('Missing semantic source judgment for '+qid+'.')
        return None
    if a.get('operation')!=operation:
        unresolved.append('Mismatched semantic operation for '+qid+'.')
        return None
    c=a.get('choice','unknown')
    if c=='unknown':
        unresolved.append('The semantic source judgment remains unknown for '+qid+'.')
        return None
    return c
def _sr_actor(choice,text):
    if choice in ('information_recipient_or_holder','contextual_party_as_recipient'):
        return ['receiving_party']
    if choice=='source_designated_actor':
        m=re.search(r'([A-Z][A-Za-z0-9_-]{1,40})\s+(?:further\s+)?(?:agrees|shall)\b',text)
        if m is not None:
            return ['named_recipient',m.group(1)]
    return None
def _sr_information(choice):
    ci=['confidential_information']
    cp=['copies_of',['confidential_information']]
    der=['derivative_materials_of',['confidential_information']]
    if choice=='confidential_information_only':
        return ci
    if choice=='copies_only':
        return cp
    if choice=='derivatives_only':
        return der
    if choice=='confidential_information_and_copies':
        return ['information_bundle',ci,cp]
    if choice=='copies_and_derivatives':
        return ['information_bundle',cp,der]
    if choice=='confidential_information_copies_and_derivatives':
        return ['information_bundle',ci,['information_bundle',cp,der]]
    return None
def _sr_trigger(choice):
    if choice=='agreement_termination':
        return ['agreement_termination']
    if choice=='service_termination':
        return ['service_termination']
    if choice=='purpose_completion':
        return ['purpose_completion']
    if choice=='supplier_request':
        return ['request_by',['disclosing_party']]
    if choice=='agreement_termination_or_request':
        return ['trigger_alternative',['agreement_termination'],['request_by',['disclosing_party']]]
    if choice=='purpose_completion_or_request':
        return ['trigger_alternative',['purpose_completion'],['request_by',['disclosing_party']]]
    return None
def _sr_scope_notes(text,unresolved):
    t=text.casefold()
    if any_phrase(t,['within one month','within ten','within 10','not later than','immediately','whichever is earlier']):
        add_once(unresolved,'A source-stated deadline or trigger-priority qualification is not representable by the available constructors.')
    if 'certify' in t or 'certification' in t:
        add_once(unresolved,'A source-stated certification duty is not representable by the available constructors.')
    if 'option' in t and any_phrase(t,['return','destroy']):
        add_once(unresolved,'The action_alternative constructor does not expose the source-designated holder of the return/destroy election.')
    if any_phrase(t,['regular ongoing records retention process','expiration of the retention period','identify in writing','written commitment to return or destroy']):
        add_once(unresolved,'A linked records process or follow-on disposal duty is not fully representable by the available constructors.')
def apply(inputs,premises):
    spans=inputs.get('source_spans',[])
    queries=_sr_queries(spans)
    if inputs.get('phase')=='plan':
        return {'queries':queries}
    statements=[]
    refs=[]
    texts=[]
    ids=[]
    for s in spans:
        raw=s.get('text','')
        if not isinstance(raw,str):
            raw=str(raw)
        texts.append(raw)
        ids.append(s.get('id'))
        parse_context(raw,[s.get('id')],statements,refs)
    i=0
    while i+1<len(texts):
        w=texts[i]+' '+texts[i+1]
        lw=w.casefold()
        if ('restrict access' in lw and 'such employees' in lw) or ('neither it nor its representatives' in lw and any_phrase(lw,['any other person','other person or organization'])):
            parse_context(w,[ids[i],ids[i+1]],statements,refs)
        i+=1
    unresolved=[]
    answers={}
    for a in inputs.get('semantic_answers',[]):
        aid=a.get('id')
        if aid in answers:
            unresolved.append('Duplicate semantic answer for '+str(aid)+'.')
        else:
            answers[aid]=a
    windows=_sr_windows(spans)
    wi=0
    while wi<len(windows):
        text,window_ids=_sr_window_text(spans,windows[wi].get('unit_ids',[]))
        t=text.casefold()
        ops=['operative_disposal_effect','operative_retention_effect','disposal_actor_role']
        if 'return' in t or 'destroy' in t:
            ops.extend(['disposal_action_allocation','disposal_trigger_role','disposal_information_scope','disposal_exception_role'])
        if any_phrase(t,['retain','retention','archiv','backup system','maintain a single copy','record copy','no copies','no copy']):
            ops.extend(['retention_information_scope','retention_limitation_role'])
        positions={}
        oi=0
        while oi<len(ops):
            positions[ops[oi]]='sr_'+str(wi)+'_'+str(oi)
            oi+=1
        ds=_sr_choice(answers,positions.get('operative_disposal_effect'),'operative_disposal_effect',unresolved)
        rs=_sr_choice(answers,positions.get('operative_retention_effect'),'operative_retention_effect',unresolved)
        effect=ds=='disposal_duty' or ds=='linked_disposal_effect' or rs in ('retention_permission','retention_prohibition','linked_retention_effect')
        actor=None
        if effect:
            ac=_sr_choice(answers,positions.get('disposal_actor_role'),'disposal_actor_role',unresolved)
            actor=_sr_actor(ac,text)
            if actor is None:
                unresolved.append('The operative actor could not be represented safely for source window '+str(wi)+'.')
        retention_info=None
        retention_condition=None
        if rs in ('retention_permission','retention_prohibition'):
            ric=_sr_choice(answers,positions.get('retention_information_scope'),'retention_information_scope',unresolved)
            retention_info=_sr_information(ric)
            if retention_info is None:
                unresolved.append('The retention information scope could not be represented safely for source window '+str(wi)+'.')
        if rs=='retention_permission':
            rlc=_sr_choice(answers,positions.get('retention_limitation_role'),'retention_limitation_role',unresolved)
            if rlc=='archival_copy_only':
                retention_condition=['retention_condition','one copy solely for archival purpose']
            elif rlc=='legally_required_record_copy':
                retention_condition=['retention_condition','record copy required by applicable law']
            elif rlc=='other_source_limited_retention':
                retention_condition=['retention_condition','source-stated limited retention']
                unresolved.append('The retention permission has a source-specific limitation retained only at the available generic condition granularity.')
            else:
                unresolved.append('The retention limitation could not be represented safely for source window '+str(wi)+'.')
            if actor is not None and retention_info is not None and retention_condition is not None:
                add_statement(statements,['retention_permission',actor,retention_info,['after_disposal'],retention_condition],window_ids)
        elif rs=='retention_prohibition':
            if actor is not None and retention_info is not None:
                add_statement(statements,['retention_prohibition',actor,retention_info,['after_disposal']],window_ids)
        elif rs=='linked_retention_effect':
            unresolved.append('A linked retention effect could not be emitted as a standalone norm for source window '+str(wi)+'.')
        if ds=='disposal_duty':
            dac=_sr_choice(answers,positions.get('disposal_action_allocation'),'disposal_action_allocation',unresolved)
            dtc=_sr_choice(answers,positions.get('disposal_trigger_role'),'disposal_trigger_role',unresolved)
            dic=_sr_choice(answers,positions.get('disposal_information_scope'),'disposal_information_scope',unresolved)
            dxc=_sr_choice(answers,positions.get('disposal_exception_role'),'disposal_exception_role',unresolved)
            info=_sr_information(dic)
            trigger=_sr_trigger(dtc)
            action=None
            if info is not None:
                if dac=='return_only':
                    action=['return_to',info,['disclosing_party']]
                elif dac=='destroy_only':
                    action=['destroy',info]
                elif dac in ('return_or_destroy_actor_choice','return_or_destroy_supplier_choice','return_or_destroy_chooser_unclear'):
                    action=['action_alternative',['return_to',info,['disclosing_party']],['destroy',info]]
                    if dac=='return_or_destroy_chooser_unclear':
                        unresolved.append('The holder of the return/destroy election remains unresolved for source window '+str(wi)+'.')
            if info is None:
                unresolved.append('The disposal information scope could not be represented safely for source window '+str(wi)+'.')
            if trigger is None:
                unresolved.append('The disposal trigger could not be represented safely for source window '+str(wi)+'.')
            if action is None:
                unresolved.append('The disposal action could not be represented safely for source window '+str(wi)+'.')
            exceptions=['no_exceptions']
            es=[]
            if dxc in ('written_direction_exception','written_direction_and_retention_exceptions'):
                es.append(['authorization_exception','different written instructions from the information supplier'])
            if dxc in ('limited_retention_exception','written_direction_and_retention_exceptions'):
                if actor is not None and retention_info is not None and retention_condition is not None:
                    es.append(['retention_exception',actor,retention_info,retention_condition])
                else:
                    unresolved.append('The embedded retention exception could not be represented completely for source window '+str(wi)+'.')
            if dxc=='unsupported_disposal_exception' or dxc is None:
                unresolved.append('The disposal exception scope could not be represented safely for source window '+str(wi)+'.')
            if es:
                exceptions=['exception_set',es[0]]
                ei=1
                while ei<len(es):
                    exceptions=['add_exception',exceptions,es[ei]]
                    ei+=1
            if actor is not None and action is not None and trigger is not None:
                add_statement(statements,['disposal_obligation',actor,action,trigger,exceptions],window_ids)
        elif ds=='linked_disposal_effect':
            unresolved.append('A linked disposal effect could not be emitted as a standalone norm for source window '+str(wi)+'.')
        if effect:
            _sr_scope_notes(text,unresolved)
        wi+=1
    has_permission=False
    has_definition=False
    needs_definition=False
    for s in statements:
        term=s.get('term')
        if isinstance(term,list) and term:
            if term[0]=='permission' or has_tag(term,'permission_exception'):
                has_permission=True
            if term[0]=='define_representative':
                has_definition=True
            if term[0] in ('permission','prohibition') and has_tag(term,'representatives_of'):
                needs_definition=True
    if refs and not has_permission:
        unresolved.append('A disclosure exception refers to another provision, but no operative recipient permission was resolved from the current source.')
    if needs_definition and not has_definition:
        unresolved.append('An operative norm uses Representatives, but their current-source membership or owner binding was not resolved.')
    return {'statements':statements,'complete':not unresolved,'unresolved':unresolved}
